<script setup lang="ts">
import { ref, onMounted, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAuth } from '../stores/auth'
import { get, post, put, patch, del } from '../api'
import { ElMessage, ElMessageBox } from 'element-plus'
import CloudTag from '../components/CloudTag.vue'
import StatusTag from '../components/StatusTag.vue'
const auth=useAuth(),route=useRoute(),router=useRouter(),items=ref<any[]>([]),jobs=ref<any[]>([]),dialog=ref(false),editing=ref<number|null>(null),tested=ref(false),regions=ref<string[]>([]),form=ref<any>({}),busy=ref(false),selectedAccount=ref(''),timer=ref<any>()
const blank=()=>({provider:'aws',partition:'global',name:'',note:'',credential_type:'ak',access_key_id:'',secret:'',role_arn:'',regions:'',auto_regions:true})
async function load(){items.value=(await get('/accounts')).items||[];jobs.value=(await get('/sync-jobs',{account_id:selectedAccount.value||undefined,page_size:20})).items||[]}
function openNew(){editing.value=null;form.value=blank();tested.value=false;regions.value=[];dialog.value=true;router.replace({query:{new:'1'}})}
function edit(a:any){editing.value=a.id;form.value={...a,secret:''};tested.value=true;regions.value=a.regions?.split(',')||[];dialog.value=true;router.replace({query:{edit:String(a.id)}})}
function close(){dialog.value=false;router.replace({query:{}})}
async function test(){busy.value=true;try{const path=editing.value?`/accounts/${editing.value}/test`:'/accounts/test';const r=await post(path,form.value);form.value.uid=r.uid;regions.value=r.regions;form.value.regions=regions.value.join(',');tested.value=true;ElMessage.success('连接成功，已发现地域')}finally{busy.value=false}}
async function save(){if(!tested.value){ElMessage.warning('请先测试连接');return}busy.value=true;try{form.value.regions=regions.value.join(',');if(editing.value)await put(`/accounts/${editing.value}`,form.value);else await post('/accounts',form.value);ElMessage.success('账号已保存');close();await load()}finally{busy.value=false}}
async function toggle(a:any){await patch(`/accounts/${a.id}`,{enabled:!a.enabled});await load()}
async function sync(a:any){await post(`/accounts/${a.id}/sync`);ElMessage.success('同步任务已启动');await load()}
async function cancel(j:any){await post(`/sync-jobs/${j.id}/cancel`);ElMessage.success('已发送取消请求');await load()}
async function remove(a:any){await ElMessageBox.confirm(`将删除「${a.name}」及其 ${a.resource_count} 项资源，操作不可撤销。`,'确认删除账号',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await del(`/accounts/${a.id}`);ElMessage.success('已删除');await load()}
watch(selectedAccount,load)
onMounted(async()=>{await load();if(route.query.new&&auth.admin)openNew();if(route.query.edit&&auth.admin){const a=items.value.find(x=>x.id===Number(route.query.edit));if(a)edit(a)}timer.value=setInterval(load,6000)})
</script><template><div class="page"><div class="page-head"><div><h1>云账号</h1><p>管理 AWS 和阿里云只读账号，查看同步进度与历史</p></div><el-button v-if="auth.admin" type="primary" @click="openNew">+ 新增云账号</el-button></div><div class="card table-card"><el-table :data="items"><el-table-column label="账号" min-width="180"><template #default="{row}"><strong>{{row.name}}</strong><div class="muted mono sm">UID {{row.uid}}</div></template></el-table-column><el-table-column label="云厂商 / 分区" width="130"><template #default="{row}"><CloudTag :provider="row.provider"/><div class="muted sm">{{row.partition==='china'?'中国区':'全球区'}}</div></template></el-table-column><el-table-column label="凭证" width="135"><template #default="{row}"><span class="mono">{{row.access_key_id}}</span><div class="muted sm">{{row.credential_type==='demo'?'演示':'AccessKey'}}</div></template></el-table-column><el-table-column label="地域" min-width="160"><template #default="{row}">{{row.regions?.split(',').length||0}} 个地域<div class="muted sm">{{row.auto_regions?'自动纳入新地域':'手动选择'}}</div></template></el-table-column><el-table-column label="资源数" prop="resource_count" width="90"/><el-table-column label="最近同步" width="170"><template #default="{row}"><StatusTag v-if="row.last_job?.id" :status="row.last_job.status"/><span v-else>—</span><div v-if="row.last_job?.status==='running'" class="muted sm">已完成 {{row.last_job.tasks_done}} / {{row.last_job.tasks_total}}</div><div v-else-if="row.last_job?.finished_at" class="muted sm">{{new Date(row.last_job.finished_at).toLocaleString('zh-CN')}}</div></template></el-table-column><el-table-column v-if="auth.admin" label="启用" width="75"><template #default="{row}"><el-switch :model-value="row.enabled" @change="toggle(row)"/></template></el-table-column><el-table-column v-if="auth.admin" label="操作" width="210" fixed="right"><template #default="{row}"><el-button text type="primary" @click="sync(row)">同步</el-button><el-button text @click="edit(row)">编辑</el-button><el-button text type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><div v-if="!items.length" class="empty">暂无云账号</div></div><div class="history card panel"><div class="section-head"><h2 class="section-title">同步历史</h2><el-select v-model="selectedAccount" clearable placeholder="全部账号" style="width:180px"><el-option v-for="a in items" :key="a.id" :value="a.id" :label="a.name"/></el-select></div><el-table :data="jobs"><el-table-column prop="started_at" label="开始时间" width="185"><template #default="{row}">{{new Date(row.started_at).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column prop="account_name" label="账号"/><el-table-column prop="triggered_by" label="触发者"/><el-table-column label="状态"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column label="进度"><template #default="{row}">{{row.tasks_done}} / {{row.tasks_total}}</template></el-table-column><el-table-column prop="resource_count" label="资源数"/><el-table-column label="错误 / 操作" min-width="220"><template #default="{row}"><span v-if="row.errors" class="error-text">{{row.errors}}</span><el-button v-if="auth.admin&&row.status==='running'" size="small" @click="cancel(row)">取消同步</el-button></template></el-table-column></el-table></div>
<el-dialog v-model="dialog" :title="editing?'编辑云账号':'新增云账号'" width="620px" @close="close"><div class="provider-cards"><button :class="{selected:form.provider==='aws'}" :disabled="!!editing" @click="form.provider='aws';tested=false">AWS <small>Amazon Web Services</small></button><button :class="{selected:form.provider==='aliyun'}" :disabled="!!editing" @click="form.provider='aliyun';tested=false">阿里云 <small>Alibaba Cloud</small></button></div><el-form label-position="top" class="account-form"><div class="grid-2"><el-form-item label="账号名称"><el-input v-model="form.name" placeholder="例如：生产账号"/></el-form-item><el-form-item label="分区"><el-select v-model="form.partition"><el-option label="全球区" value="global"/><el-option label="中国区" value="china"/></el-select></el-form-item></div><el-form-item label="备注"><el-input v-model="form.note" placeholder="可选"/></el-form-item><div class="grid-2"><el-form-item label="AccessKey ID"><el-input v-model="form.access_key_id" placeholder="只读 AccessKey" @input="tested=false"/></el-form-item><el-form-item :label="editing?'AccessKey Secret（留空不修改）':'AccessKey Secret'"><el-input v-model="form.secret" type="password" show-password @input="tested=false"/></el-form-item></div><el-form-item label="角色 ARN（可选）"><el-input v-model="form.role_arn"/></el-form-item><el-button :loading="busy" @click="test">测试连接</el-button><span v-if="tested" class="test-ok">✓ 已连接 · UID {{form.uid}}</span><div v-if="tested" class="regions"><div class="section-head"><h3 class="section-title">同步地域</h3><el-checkbox v-model="form.auto_regions">自动纳入新地域</el-checkbox></div><el-checkbox-group v-model="regions"><el-checkbox v-for="r in ['cn-hangzhou','cn-shanghai','cn-beijing','cn-hongkong','us-east-1','ap-northeast-1']" :key="r" :label="r" :value="r"/></el-checkbox-group></div></el-form><template #footer><el-button @click="close">取消</el-button><el-button type="primary" :disabled="!tested" :loading="busy" @click="save">保存账号</el-button></template></el-dialog></div></template>
<style scoped>.table-card{padding:8px 16px}.sm{font-size:11px;margin-top:5px}.history{margin-top:16px}.error-text{color:var(--amber);font-size:12px}.provider-cards{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:22px}.provider-cards button{background:white;border:1px solid var(--border);border-radius:8px;text-align:left;padding:16px;font-size:16px;font-weight:600;cursor:pointer}.provider-cards button.selected{border-color:var(--primary);background:var(--primary-soft);color:var(--primary)}.provider-cards small{display:block;font-size:11px;color:var(--subtle);font-weight:400;margin-top:5px}.account-form .grid-2{gap:15px}.test-ok{margin-left:12px;color:var(--green);font-size:12px}.regions{border:1px solid var(--border);border-radius:8px;padding:14px;margin-top:18px}</style>
